insert into system_email_templates (key, subject, html) values
  ('account_registered', 'Tu cuenta de NinjaPos está creada', '<div style="font-family:system-ui,Segoe UI,Arial,sans-serif;max-width:520px;margin:0 auto;background:#ffffff;border:1px solid #eef0f3;border-radius:14px;overflow:hidden"><div style="padding:28px 32px 8px;text-align:center"><img src="https://ninja-soft-pos.vercel.app/brand/ninjapos-logo-light-mode.webp" alt="NinjaPos" style="max-height:26px;display:inline-block" /><div style="height:3px;width:48px;background:#f97316;border-radius:99px;margin:18px auto 0"></div></div><div style="padding:20px 32px 32px;color:#1f2937;line-height:1.6;font-size:15px"><p>¡Hola {{nombre}}! 🎉</p><p>Creamos tu cuenta en <b>NinjaPos</b>. Ya podés entrar y empezar a configurar <b>{{negocio}}</b>.</p><div style="text-align:center;margin:22px 0 4px"><a href="https://ninja-soft-pos.vercel.app/login" style="display:inline-block;background:#f97316;color:#ffffff;text-decoration:none;font-weight:600;padding:12px 26px;border-radius:10px;font-size:15px">Ingresar a NinjaPos</a></div></div><div style="background:#09051C;padding:18px 12px;text-align:center"><img src="https://ninja-soft-pos.vercel.app/brand/ninjapos-logo-dark-mode.webp" alt="NinjaPos" style="max-height:20px;display:inline-block" /><div style="color:#9ca3af;font-size:11px;margin-top:8px">Enviado con NinjaPos</div></div></div>'),
  ('email_confirmation', 'Confirmá tu email para activar tu cuenta', '<div style="font-family:system-ui,Segoe UI,Arial,sans-serif;max-width:520px;margin:0 auto;background:#ffffff;border:1px solid #eef0f3;border-radius:14px;overflow:hidden"><div style="padding:28px 32px 8px;text-align:center"><img src="https://ninja-soft-pos.vercel.app/brand/ninjapos-logo-light-mode.webp" alt="NinjaPos" style="max-height:26px;display:inline-block" /><div style="height:3px;width:48px;background:#f97316;border-radius:99px;margin:18px auto 0"></div></div><div style="padding:20px 32px 32px;color:#1f2937;line-height:1.6;font-size:15px"><p>Hola {{nombre}},</p><p>Confirmá tu dirección de email para terminar de activar tu cuenta de NinjaPos.</p><div style="text-align:center;margin:22px 0 4px"><a href="{{link}}" style="display:inline-block;background:#f97316;color:#ffffff;text-decoration:none;font-weight:600;padding:12px 26px;border-radius:10px;font-size:15px">Confirmar mi email</a></div><p style="color:#6b7280;font-size:13px;margin-top:16px">Si no creaste esta cuenta, podés ignorar este email.</p></div><div style="background:#09051C;padding:18px 12px;text-align:center"><img src="https://ninja-soft-pos.vercel.app/brand/ninjapos-logo-dark-mode.webp" alt="NinjaPos" style="max-height:20px;display:inline-block" /><div style="color:#9ca3af;font-size:11px;margin-top:8px">Enviado con NinjaPos</div></div></div>'),
  ('welcome', '¡Bienvenido a {{negocio}}!', '<div style="font-family:system-ui,Segoe UI,Arial,sans-serif;max-width:520px;margin:0 auto;background:#ffffff;border:1px solid #eef0f3;border-radius:14px;overflow:hidden"><div style="padding:28px 32px 8px;text-align:center"><img src="https://ninja-soft-pos.vercel.app/brand/ninjapos-logo-light-mode.webp" alt="NinjaPos" style="max-height:26px;display:inline-block" /><div style="height:3px;width:48px;background:#f97316;border-radius:99px;margin:18px auto 0"></div></div><div style="padding:20px 32px 32px;color:#1f2937;line-height:1.6;font-size:15px"><p>Hola {{nombre}} 👋</p><p>Te damos la bienvenida a <b>{{negocio}}</b>. Ya podés empezar a usar el sistema y vender en minutos.</p><div style="text-align:center;margin:22px 0 4px"><a href="https://ninja-soft-pos.vercel.app/login" style="display:inline-block;background:#f97316;color:#ffffff;text-decoration:none;font-weight:600;padding:12px 26px;border-radius:10px;font-size:15px">Empezar ahora</a></div></div><div style="background:#09051C;padding:18px 12px;text-align:center"><img src="https://ninja-soft-pos.vercel.app/brand/ninjapos-logo-dark-mode.webp" alt="NinjaPos" style="max-height:20px;display:inline-block" /><div style="color:#9ca3af;font-size:11px;margin-top:8px">Enviado con NinjaPos</div></div></div>'),
  ('password_recovery', 'Restablecé tu contraseña de NinjaPos', '<div style="font-family:system-ui,Segoe UI,Arial,sans-serif;max-width:520px;margin:0 auto;background:#ffffff;border:1px solid #eef0f3;border-radius:14px;overflow:hidden"><div style="padding:28px 32px 8px;text-align:center"><img src="https://ninja-soft-pos.vercel.app/brand/ninjapos-logo-light-mode.webp" alt="NinjaPos" style="max-height:26px;display:inline-block" /><div style="height:3px;width:48px;background:#f97316;border-radius:99px;margin:18px auto 0"></div></div><div style="padding:20px 32px 32px;color:#1f2937;line-height:1.6;font-size:15px"><p>Hola {{nombre}},</p><p>Pediste restablecer tu contraseña. Hacé clic en el botón para elegir una nueva.</p><div style="text-align:center;margin:22px 0 4px"><a href="{{link}}" style="display:inline-block;background:#f97316;color:#ffffff;text-decoration:none;font-weight:600;padding:12px 26px;border-radius:10px;font-size:15px">Cambiar mi contraseña</a></div><p style="color:#6b7280;font-size:13px;margin-top:16px">Si no fuiste vos, ignorá este email: tu contraseña no cambia.</p></div><div style="background:#09051C;padding:18px 12px;text-align:center"><img src="https://ninja-soft-pos.vercel.app/brand/ninjapos-logo-dark-mode.webp" alt="NinjaPos" style="max-height:20px;display:inline-block" /><div style="color:#9ca3af;font-size:11px;margin-top:8px">Enviado con NinjaPos</div></div></div>'),
  ('trial_started', 'Arrancó tu prueba gratis de NinjaPos', '<div style="font-family:system-ui,Segoe UI,Arial,sans-serif;max-width:520px;margin:0 auto;background:#ffffff;border:1px solid #eef0f3;border-radius:14px;overflow:hidden"><div style="padding:28px 32px 8px;text-align:center"><img src="https://ninja-soft-pos.vercel.app/brand/ninjapos-logo-light-mode.webp" alt="NinjaPos" style="max-height:26px;display:inline-block" /><div style="height:3px;width:48px;background:#f97316;border-radius:99px;margin:18px auto 0"></div></div><div style="padding:20px 32px 32px;color:#1f2937;line-height:1.6;font-size:15px"><p>¡Listo! Empezó tu prueba gratis de <b>NinjaPos</b> para <b>{{negocio}}</b>.</p><p>Tenés <b>{{dias}} días</b> con todo desbloqueado (hasta el {{vence}}). Probá el punto de venta, cargá tus productos y sumá a tu equipo.</p><div style="text-align:center;margin:22px 0 4px"><a href="https://ninja-soft-pos.vercel.app/login" style="display:inline-block;background:#f97316;color:#ffffff;text-decoration:none;font-weight:600;padding:12px 26px;border-radius:10px;font-size:15px">Explorar NinjaPos</a></div></div><div style="background:#09051C;padding:18px 12px;text-align:center"><img src="https://ninja-soft-pos.vercel.app/brand/ninjapos-logo-dark-mode.webp" alt="NinjaPos" style="max-height:20px;display:inline-block" /><div style="color:#9ca3af;font-size:11px;margin-top:8px">Enviado con NinjaPos</div></div></div>'),
  ('trial_ending', 'Tu prueba de NinjaPos vence pronto', '<div style="font-family:system-ui,Segoe UI,Arial,sans-serif;max-width:520px;margin:0 auto;background:#ffffff;border:1px solid #eef0f3;border-radius:14px;overflow:hidden"><div style="padding:28px 32px 8px;text-align:center"><img src="https://ninja-soft-pos.vercel.app/brand/ninjapos-logo-light-mode.webp" alt="NinjaPos" style="max-height:26px;display:inline-block" /><div style="height:3px;width:48px;background:#f97316;border-radius:99px;margin:18px auto 0"></div></div><div style="padding:20px 32px 32px;color:#1f2937;line-height:1.6;font-size:15px"><p>Tu período de prueba termina en <b>{{dias}} días</b> ({{vence}}).</p><p>Activá tu plan para no perder acceso a <b>{{negocio}}</b> ni a tu información.</p><div style="text-align:center;margin:22px 0 4px"><a href="https://ninja-soft-pos.vercel.app/login" style="display:inline-block;background:#f97316;color:#ffffff;text-decoration:none;font-weight:600;padding:12px 26px;border-radius:10px;font-size:15px">Activar mi plan</a></div></div><div style="background:#09051C;padding:18px 12px;text-align:center"><img src="https://ninja-soft-pos.vercel.app/brand/ninjapos-logo-dark-mode.webp" alt="NinjaPos" style="max-height:20px;display:inline-block" /><div style="color:#9ca3af;font-size:11px;margin-top:8px">Enviado con NinjaPos</div></div></div>'),
  ('subscription_activated', 'Tu suscripción de NinjaPos está activa', '<div style="font-family:system-ui,Segoe UI,Arial,sans-serif;max-width:520px;margin:0 auto;background:#ffffff;border:1px solid #eef0f3;border-radius:14px;overflow:hidden"><div style="padding:28px 32px 8px;text-align:center"><img src="https://ninja-soft-pos.vercel.app/brand/ninjapos-logo-light-mode.webp" alt="NinjaPos" style="max-height:26px;display:inline-block" /><div style="height:3px;width:48px;background:#f97316;border-radius:99px;margin:18px auto 0"></div></div><div style="padding:20px 32px 32px;color:#1f2937;line-height:1.6;font-size:15px"><p>¡Gracias por sumarte! Tu plan <b>{{plan}}</b> ya está activo para <b>{{negocio}}</b>.</p><p>Tu próxima renovación es el {{vence}}. El cobro es automático por Mercado Pago.</p><div style="text-align:center;margin:22px 0 4px"><a href="https://ninja-soft-pos.vercel.app/login" style="display:inline-block;background:#f97316;color:#ffffff;text-decoration:none;font-weight:600;padding:12px 26px;border-radius:10px;font-size:15px">Ir a mi panel</a></div></div><div style="background:#09051C;padding:18px 12px;text-align:center"><img src="https://ninja-soft-pos.vercel.app/brand/ninjapos-logo-dark-mode.webp" alt="NinjaPos" style="max-height:20px;display:inline-block" /><div style="color:#9ca3af;font-size:11px;margin-top:8px">Enviado con NinjaPos</div></div></div>'),
  ('subscription_cancelled', 'Cancelamos tu suscripción de NinjaPos', '<div style="font-family:system-ui,Segoe UI,Arial,sans-serif;max-width:520px;margin:0 auto;background:#ffffff;border:1px solid #eef0f3;border-radius:14px;overflow:hidden"><div style="padding:28px 32px 8px;text-align:center"><img src="https://ninja-soft-pos.vercel.app/brand/ninjapos-logo-light-mode.webp" alt="NinjaPos" style="max-height:26px;display:inline-block" /><div style="height:3px;width:48px;background:#f97316;border-radius:99px;margin:18px auto 0"></div></div><div style="padding:20px 32px 32px;color:#1f2937;line-height:1.6;font-size:15px"><p>Tu suscripción de <b>{{negocio}}</b> quedó cancelada.</p><p>Tenés acceso hasta el {{vence}}. Después, tu cuenta se pausa pero tu información queda guardada por si querés volver.</p><div style="text-align:center;margin:22px 0 4px"><a href="https://ninja-soft-pos.vercel.app/login" style="display:inline-block;background:#f97316;color:#ffffff;text-decoration:none;font-weight:600;padding:12px 26px;border-radius:10px;font-size:15px">Reactivar cuando quieras</a></div></div><div style="background:#09051C;padding:18px 12px;text-align:center"><img src="https://ninja-soft-pos.vercel.app/brand/ninjapos-logo-dark-mode.webp" alt="NinjaPos" style="max-height:20px;display:inline-block" /><div style="color:#9ca3af;font-size:11px;margin-top:8px">Enviado con NinjaPos</div></div></div>'),
  ('payment_ok', 'Recibimos tu pago — gracias', '<div style="font-family:system-ui,Segoe UI,Arial,sans-serif;max-width:520px;margin:0 auto;background:#ffffff;border:1px solid #eef0f3;border-radius:14px;overflow:hidden"><div style="padding:28px 32px 8px;text-align:center"><img src="https://ninja-soft-pos.vercel.app/brand/ninjapos-logo-light-mode.webp" alt="NinjaPos" style="max-height:26px;display:inline-block" /><div style="height:3px;width:48px;background:#f97316;border-radius:99px;margin:18px auto 0"></div></div><div style="padding:20px 32px 32px;color:#1f2937;line-height:1.6;font-size:15px"><p>¡Listo! Recibimos tu pago de <b>{{monto}}</b> por la suscripción de <b>{{negocio}}</b>.</p><p>Tu acceso sigue activo. Tu próxima renovación es el {{vence}}.</p></div><div style="background:#09051C;padding:18px 12px;text-align:center"><img src="https://ninja-soft-pos.vercel.app/brand/ninjapos-logo-dark-mode.webp" alt="NinjaPos" style="max-height:20px;display:inline-block" /><div style="color:#9ca3af;font-size:11px;margin-top:8px">Enviado con NinjaPos</div></div></div>'),
  ('payment_failed', 'Hubo un problema con tu cobro', '<div style="font-family:system-ui,Segoe UI,Arial,sans-serif;max-width:520px;margin:0 auto;background:#ffffff;border:1px solid #eef0f3;border-radius:14px;overflow:hidden"><div style="padding:28px 32px 8px;text-align:center"><img src="https://ninja-soft-pos.vercel.app/brand/ninjapos-logo-light-mode.webp" alt="NinjaPos" style="max-height:26px;display:inline-block" /><div style="height:3px;width:48px;background:#f97316;border-radius:99px;margin:18px auto 0"></div></div><div style="padding:20px 32px 32px;color:#1f2937;line-height:1.6;font-size:15px"><p>No pudimos confirmar el pago de tu suscripción de <b>{{negocio}}</b>.</p><p>Revisá tu medio de pago en Mercado Pago para no perder acceso. Vamos a reintentar el cobro automáticamente.</p><div style="text-align:center;margin:22px 0 4px"><a href="https://ninja-soft-pos.vercel.app/login" style="display:inline-block;background:#f97316;color:#ffffff;text-decoration:none;font-weight:600;padding:12px 26px;border-radius:10px;font-size:15px">Revisar mi pago</a></div></div><div style="background:#09051C;padding:18px 12px;text-align:center"><img src="https://ninja-soft-pos.vercel.app/brand/ninjapos-logo-dark-mode.webp" alt="NinjaPos" style="max-height:20px;display:inline-block" /><div style="color:#9ca3af;font-size:11px;margin-top:8px">Enviado con NinjaPos</div></div></div>'),
  ('payment_reminder', 'Tu suscripción se renueva pronto', '<div style="font-family:system-ui,Segoe UI,Arial,sans-serif;max-width:520px;margin:0 auto;background:#ffffff;border:1px solid #eef0f3;border-radius:14px;overflow:hidden"><div style="padding:28px 32px 8px;text-align:center"><img src="https://ninja-soft-pos.vercel.app/brand/ninjapos-logo-light-mode.webp" alt="NinjaPos" style="max-height:26px;display:inline-block" /><div style="height:3px;width:48px;background:#f97316;border-radius:99px;margin:18px auto 0"></div></div><div style="padding:20px 32px 32px;color:#1f2937;line-height:1.6;font-size:15px"><p>Tu suscripción de <b>{{negocio}}</b> se renueva el <b>{{vence}}</b>.</p><p>El cobro es automático por Mercado Pago; verificá que tu medio de pago esté activo para no perder acceso.</p></div><div style="background:#09051C;padding:18px 12px;text-align:center"><img src="https://ninja-soft-pos.vercel.app/brand/ninjapos-logo-dark-mode.webp" alt="NinjaPos" style="max-height:20px;display:inline-block" /><div style="color:#9ca3af;font-size:11px;margin-top:8px">Enviado con NinjaPos</div></div></div>'),
  ('addon_ai_activated', 'Activaste el Asistente IA en NinjaPos', '<div style="font-family:system-ui,Segoe UI,Arial,sans-serif;max-width:520px;margin:0 auto;background:#ffffff;border:1px solid #eef0f3;border-radius:14px;overflow:hidden"><div style="padding:28px 32px 8px;text-align:center"><img src="https://ninja-soft-pos.vercel.app/brand/ninjapos-logo-light-mode.webp" alt="NinjaPos" style="max-height:26px;display:inline-block" /><div style="height:3px;width:48px;background:#f97316;border-radius:99px;margin:18px auto 0"></div></div><div style="padding:20px 32px 32px;color:#1f2937;line-height:1.6;font-size:15px"><p>¡Buenísimo! Activaste el <b>Asistente IA</b> en <b>{{negocio}}</b>.</p><p>Ya podés pedirle reportes, resúmenes y ayuda en lenguaje natural desde tu panel.</p><div style="text-align:center;margin:22px 0 4px"><a href="https://ninja-soft-pos.vercel.app/login" style="display:inline-block;background:#f97316;color:#ffffff;text-decoration:none;font-weight:600;padding:12px 26px;border-radius:10px;font-size:15px">Probar el Asistente IA</a></div></div><div style="background:#09051C;padding:18px 12px;text-align:center"><img src="https://ninja-soft-pos.vercel.app/brand/ninjapos-logo-dark-mode.webp" alt="NinjaPos" style="max-height:20px;display:inline-block" /><div style="color:#9ca3af;font-size:11px;margin-top:8px">Enviado con NinjaPos</div></div></div>'),
  ('addon_ai_cancelled', 'Diste de baja el Asistente IA', '<div style="font-family:system-ui,Segoe UI,Arial,sans-serif;max-width:520px;margin:0 auto;background:#ffffff;border:1px solid #eef0f3;border-radius:14px;overflow:hidden"><div style="padding:28px 32px 8px;text-align:center"><img src="https://ninja-soft-pos.vercel.app/brand/ninjapos-logo-light-mode.webp" alt="NinjaPos" style="max-height:26px;display:inline-block" /><div style="height:3px;width:48px;background:#f97316;border-radius:99px;margin:18px auto 0"></div></div><div style="padding:20px 32px 32px;color:#1f2937;line-height:1.6;font-size:15px"><p>Diste de baja el <b>Asistente IA</b> de <b>{{negocio}}</b>.</p><p>Lo vas a poder seguir usando hasta el {{vence}}. Después, el resto de tu plan sigue igual.</p></div><div style="background:#09051C;padding:18px 12px;text-align:center"><img src="https://ninja-soft-pos.vercel.app/brand/ninjapos-logo-dark-mode.webp" alt="NinjaPos" style="max-height:20px;display:inline-block" /><div style="color:#9ca3af;font-size:11px;margin-top:8px">Enviado con NinjaPos</div></div></div>')
